use strict;
use warnings;
use File::Find;
use File::Slurp;

my $root = '/bench/repo';
my $internal = "$root/internal";

# Parse declarations in internal/ non-test files
my @decls;  # { name, qual, path, line, is_method, recv, pkg }

sub parse_file {
    my ($path) = @_;
    return if $path =~ /_test\.go$/;
    my $rel = $path; $rel =~ s/^\Q$root\E\/?//;
    my $content = read_file($path);
    my ($pkg) = $content =~ /^package\s+(\w+)/m;
    return unless $pkg;

    my @lines = split /\n/, $content;
    for my $i (0..$#lines) {
        my $line = $lines[$i];
        next unless $line =~ /^\s*func\s+/;
        if ($line =~ /^\s*func\s+\(([^)]+)\)\s+(\w+)\s*\(/) {
            my ($recv, $name) = ($1, $2);
            my ($recv_type) = $recv =~ /(\*?\w+)\s*$/;
            $recv_type =~ s/^\*//;
            push @decls, {
                name => $name,
                qual => "$recv_type.$name",
                path => $rel,
                line => $i+1,
                is_method => 1,
                recv => $recv_type,
                pkg => $pkg,
            };
        } elsif ($line =~ /^\s*func\s+(\w+)\s*\(/) {
            my $name = $1;
            push @decls, {
                name => $name,
                qual => "$pkg.$name",
                path => $rel,
                line => $i+1,
                is_method => 0,
                pkg => $pkg,
            };
        }
    }
}

find({ wanted => sub { parse_file($File::Find::name) if /\.go$/ && -f $_ && index($File::Find::name, '/internal/') >= 0 }, no_chdir => 1 }, $internal);

# Build package alias map from imports - simplified: just count by import path ending
