my @files;
find({ wanted => sub {
    return unless /\.go$/;
    return if /_test\.go$/;
    return if /proto\/gen/;
    push @files, $File::Find::name;
}, no_chdir => 1 }, $root);

# For each decl, count approximate call sites
my %fanin;

for my $d (@decls) {
    my $name = $d->{name};
    my $count = 0;
    my @patterns;

    if ($d->{is_method}) {
        # .MethodName( but not declaration line
        push @patterns, qr/\.$name\s*\(/;
    } else {
        # For exported: package.Name or bare Name in other contexts
        if ($name =~ /^[A-Z]/) {
            # import alias patterns - count \bName\( and \.\w*Name\( and pkg paths
            my $pkg = $d->{pkg};
            push @patterns, qr/\b$name\s*\(/;
            # also count explicit import path style like markdown.New
            push @patterns, qr/\.$name\s*\(/;
        } else {
            # unexported - only count within same package files... hard. skip or same dir
            push @patterns, qr/\b$name\s*\(/;
        }
    }

    for my $f (@files) {
        my $content = read_file($f);
        my $rel = $f; $rel =~ s/^\Q$root\E\/?//;
        my @lines = split /\n/, $content;
        for my $i (0..$#lines) {
            my $line = $lines[$i];
            next if $rel eq $d->{path} && ($i+1) == $d->{line}; # skip own decl
            next if $line =~ /^\s*func\s+/; # skip declarations
            for my $p (@patterns) {
