my @all_files = map { chomp; $_ } `cat /tmp/all_files.txt`;

sub read_file {
    my ($path) = @_;
    open my $fh, '<', $path or return '';
    local $/; my $c = <$fh>; close $fh;
    return $c;
}

# map internal package dir -> package name and import suffix
my %pkg_dir; # path like internal/markdown -> { pkg => markdown, suffix => internal/markdown }
for my $path (@internal_files) {
    my $rel = $path; $rel =~ s/^\Q$root\E\/?//;
    my $content = read_file($path);
    my ($pkg) = $content =~ /^package\s+(\w+)/m;
    next unless $pkg;
    my ($dir) = $rel =~ /^(internal\/.*?)\/[^\/]+$/;
    $pkg_dir{$dir} = { pkg => $pkg, dir => $dir } unless exists $pkg_dir{$dir};
}

my @decls;
for my $path (@internal_files) {
    my $rel = $path; $rel =~ s/^\Q$root\E\/?//;
    my ($dir) = $rel =~ /^(internal\/.*?)\/[^\/]+$/;
    my $content = read_file($path);
    my ($pkg) = $content =~ /^package\s+(\w+)/m;
    next unless $pkg;
    my @lines = split /\n/, $content;
    for my $i (0..$#lines) {
        my $line = $lines[$i];
        next unless $line =~ /^\s*func\s+/;
        if ($line =~ /^\s*func\s+\(([^)]+)\)\s+(\w+)\s*\(/) {
            my ($recv, $name) = ($1, $2);
            my ($recv_type) = $recv =~ /(\*?\w+)\s*$/;
            $recv_type =~ s/^\*//;
            push @decls, { name=>$name, qual=>"$recv_type.$name", path=>$rel, line=>$i+1, is_method=>1, pkg=>$pkg, dir=>$dir, recv=>$recv_type };
        } elsif ($line =~ /^\s*func\s+(\w+)\s*\(/) {
            my $name = $1;
            push @decls, { name=>$name, qual=>"$pkg.$name", path=>$rel, line=>$i+1, is_method=>0, pkg=>$pkg, dir=>$dir };
        }
    }
}

# Build import alias map per file: alias -> import path
sub parse_imports {
    my ($content) = @_;
    my %aliases;
    while ($content =~ /^\s*import\s+(?:\(\s*(.*?)\s*\)|"([^"]+)")/gms) {
        my $block = $1 // $2;
        next unless defined $block;
        if (!defined $1) {
            my $path = $2;
            my $alias = $path =~ m{/(\w+)$} ? $1 : $path;
            $aliases{$alias} = $path;
        } else {
            for my $line (split /\n/, $block) {
                next unless $line =~ /"/;
                if ($line =~ /(\w+)\s+"([^"]+)"/) {
                    $aliases{$1} = $2;
                } elsif ($line =~ /"([^"]+)"/) {
                    my $path = $1;
                    my $alias = $path =~ m{/(\w+)$} ? $1 : $path;
                    $aliases{$alias} = $path;
                }
            }
        }
    }
    return %aliases;
}

my %file_content;
my %file_imports;
for my $f (@all_files) {
    my $c = read_file($f);
    $file_content{$f} = $c;
    $file_imports{$f} = { parse_imports($c) };
}

my %fanin;
for my $d (@decls) {
    my $name = $d->{name};
    my $suffix = $d->{dir}; # internal/foo/bar -> use full internal path from dir
    my $count = 0;
    for my $f (@all_files) {
        my $rel = $f; $rel =~ s/^\Q$root\E\/?//;
        my $content = $file_content{$f};
        my @lines = split /\n/, $content;
        my %imports = %{$file_imports{$f}};

        # find aliases that import this package dir
        my @matching_aliases;
        for my $alias (keys %imports) {
            push @matching_aliases, $alias if index($imports{$alias}, $suffix) >= 0 || $imports{$alias} =~ /\Q$suffix\E/;
        }
        # also default pkg name if imported as last segment
        push @matching_aliases, $d->{pkg};

        for my $i (0..$#lines) {
            my $line = $lines[$i];
            next if $rel eq $d->{path} && ($i+1) == $d->{line};
            next if $line =~ /^\s*func\s+/;

            my $hit = 0;
            if ($d->{is_method}) {
                # Method: look for .Name( - harder to attribute to specific type
                $hit = 1 if $line =~ /\.$name\s*\(/;
            } else {
                if ($name =~ /^[A-Z]/) {
                    for my $alias (keys %imports) {
                        next unless $imports{$alias} =~ /\Q$d->{dir}\E/ || index($imports{$alias}, $d->{dir}) >= 0;
                        $hit = 1 if $line =~ /\b\Q$alias\E\.$name\s*\(/;
                    }
                    # same-package call
                    my ($fpkg) = $content =~ /^package\s+(\w+)/m;
                    if ($fpkg && $fpkg eq $d->{pkg} && index($rel, $d->{dir}) == 0) {
                        $hit = 1 if $line =~ /\b$name\s*\(/;
                    }
                } else {
                    my ($fpkg) = $content =~ /^package\s+(\w+)/m;
                    next unless $fpkg && $fpkg eq $d->{pkg} && index($rel, $d->{dir}) == 0;
                    $hit = 1 if $line =~ /\b$name\s*\(/;
                }
            }
            $count++ if $hit;
        }
    }
    $fanin{"$d->{qual}|$d->{path}:$d->{line}"} = $count;
}

my @sorted = sort { $fanin{$b} <=> $fanin{$a} } keys %fanin;
print "Top 25 (import-aware for exported funcs):\n";
for my $i (0..24) {
    last unless defined $sorted[$i];
    my ($sym, $loc) = split /\|/, $sorted[$i], 2;
    print "$fanin{$sorted[$i]}\t$sym — $loc\n";
}
